import {it,expect} from 'vitest';
import {advanceForecastEpisode,seedForecastEpisode,forecastEpisodeDecision,forecastSignal,severeForecast,bootstrapForecastEpisode,type ForecastEpisode} from '../supabase/functions/watch-rain/forecastEpisode';
import {guardedPush} from '../supabase/functions/watch-rain/deliveryGuard';
const start=():ForecastEpisode=>({...seedForecastEpisode('existing',{last_notified_at:'2026-10-29T03:45:00Z'},false),lastForecastAt:'20261029034000'});
it('keeps one approach intent through repeated dry observations, INFO and changing target minutes',()=>{let s=start();for(const v of ['20261029034500','20261029035000','20261029035500','20261029040000']){s=advanceForecastEpisode(s,'ACTIVE',v,'unused');expect(s.id).toBe('existing');expect(forecastEpisodeDecision(s,true,true,0,false).notify).toBe(false);}});
it('does not close on one or two cancelled forecasts, repeated issuance, or unknown gaps',()=>{let s=start();s=advanceForecastEpisode(s,'CLEAR','20261029034500','new');s=advanceForecastEpisode(s,'CLEAR','20261029034500','new');expect(s.clearForecasts).toBe(1);s=advanceForecastEpisode(s,'CLEAR','20261029035000','new');expect(s.active).toBe(true);s=advanceForecastEpisode(s,'UNKNOWN','20261029035500','new');expect(s.clearForecasts).toBe(0);expect(s.approachNotified).toBe(true);});
it('rearms only after three fresh complete dry forecasts and a subsequent new approach',()=>{let s=start();for(const v of ['20261029034500','20261029035000','20261029035500'])s=advanceForecastEpisode(s,'CLEAR',v,'unused');expect(s.active).toBe(false);expect(forecastEpisodeDecision(s,true,false,0,false).notify).toBe(false);s=advanceForecastEpisode(s,'ACTIVE','20261029040000','new-episode');expect(s.id).toBe('new-episode');expect(forecastEpisodeDecision(s,true,true,0,false).notify).toBe(true);});
it('never lets an old forecast reverse a new episode',()=>{const s=advanceForecastEpisode(start(),'ACTIVE','20261029035500','new');expect(advanceForecastEpisode(s,'CLEAR','20261029034500','bad')).toEqual(s);});
it('sends severe only once per episode regardless of 30 to 50 to 80 escalation and respects OFF',()=>{const first={...start(),peakSevere:0};expect(forecastEpisodeDecision(first,true,true,1,false)).toMatchObject({notify:true,severe:true,key:'existing/SEVERE'});const sent={...first,peakSevere:1};expect(forecastEpisodeDecision(sent,true,true,2,false).severe).toBe(false);expect(forecastEpisodeDecision({...sent,peakSevere:2},true,true,3,false).severe).toBe(false);expect(forecastEpisodeDecision(sent,false,true,3,true).notify).toBe(false);expect(forecastEpisodeDecision(sent,true,false,0,true).key).toBe('existing/ENDING');});
it('seeds existing delivery conservatively and rearms only with verified prior forecast cancellation',()=>{expect(seedForecastEpisode('id',{last_notified_at:'old'},false).approachNotified).toBe(true);expect(seedForecastEpisode('id',{last_notified_at:'old'},true).approachNotified).toBe(false);});
it('does not call incomplete, unknown or empty forecasts clear',()=>{const now=Date.parse('2026-10-29T03:45:00Z');const r={interpretationEnabled:true,interpretation:{state:'DRY'},forecast:[{baseTime:'20261029034000',validTime:'20261029035000',status:'UNKNOWN_PIXEL'}]};expect(forecastSignal(r,now).signal).toBe('UNKNOWN');r.forecast[0].status='NO_RAIN';expect(forecastSignal(r,now).signal).toBe('CLEAR');r.interpretation.state='INSUFFICIENT_DATA';expect(forecastSignal(r,now).signal).toBe('UNKNOWN');});
it('parses JMA timestamps for 30/50/80 escalation instead of Date.parse on fourteen digits',()=>{const f=severeForecast([{baseTime:'20261029034000',validTime:'20261029035000',status:'RAIN',intensityClass:'30_TO_50'},{baseTime:'20261029034000',validTime:'20261029035500',status:'RAIN',intensityClass:'GTE_80'}],Date.parse('2026-10-29T03:45:00Z'));expect(f?.intensityClass).toBe('GTE_80');});
it('a permanent intent allows only one mock transport, including parallel senders',async()=>{let claimed=false,sends=0;const run=()=>guardedPush({claim:async()=>{if(claimed)return null;claimed=true;return 'intent';},send:async()=>{sends++;},finish:async()=>{}});await Promise.all([run(),run()]);expect(sends).toBe(1);});
it('accepted send followed by outcome DB failure is not sent again',async()=>{let claimed=false,sends=0;const run=()=>guardedPush({claim:async()=>{if(claimed)return null;claimed=true;return 'intent';},send:async()=>{sends++;},finish:async()=>{throw Error('DB failure');}});await expect(run()).rejects.toThrow('DB failure');expect(await run()).toBe('SKIPPED');expect(sends).toBe(1);});
it.each([0,500,408,429])('keeps ambiguous transport %s uncertain and never grants retry',async(code)=>{let claimed=false;const states:string[]=[];const run=()=>guardedPush({claim:async()=>{if(claimed)return null;claimed=true;return 'id';},send:async()=>{throw {statusCode:code};},finish:async(_,s)=>{states.push(s);}});await run();expect(await run()).toBe('SKIPPED');expect(states).toEqual(['UNCERTAIN']);});
it('treats invalid endpoints terminal without blocking another subscription',async()=>{const states:string[]=[];for(const code of [410,0])await guardedPush({claim:async()=>String(code),send:async()=>{if(code)throw {statusCode:code};},finish:async(_,s)=>{states.push(s);}});expect(states).toEqual(['FAILED_TERMINAL','ACCEPTED']);});

it('breaks forecast cancellation confirmation on an outage with no issuance',()=>{const s={...start(),clearForecasts:2};expect(advanceForecastEpisode(s,'UNKNOWN',null,'unused').clearForecasts).toBe(0);});

it('bootstraps a new approach from three prior clear forecasts without counting its current ACTIVE row as a cancellation',()=>{
 const recent=[{source_valid_at:'20261029040000',event_type:'ACTIONABLE_RAIN_APPROACHING',checked_at:'2026-10-29T04:05:00Z'},...['035500','035000','034500'].map(t=>({source_valid_at:'20261029'+t,event_type:'RAIN_CLEAR',checked_at:'2026-10-29T04:00:00Z'}))];
 const s=bootstrapForecastEpisode('old',{last_notified_at:'2026-10-29T03:00:00Z'},recent,'20261029040000');expect(s.active).toBe(false);const next=advanceForecastEpisode(s,'ACTIVE','20261029040000','new');expect(forecastEpisodeDecision(next,true,true,0,false).notify).toBe(true);
});
it('carries two prior clear issuances into the third current complete-clear forecast, ignoring duplicate rows',()=>{
 const rows=['20261029035500','20261029035500','20261029035000'].map(t=>({source_valid_at:t,event_type:'RAIN_CLEAR',checked_at:'2026-10-29T04:00:00Z'}));const s=bootstrapForecastEpisode('old',{last_notified_at:'2026-10-29T03:00:00Z'},rows,'20261029040000');expect(s.clearForecasts).toBe(2);expect(advanceForecastEpisode(s,'CLEAR','20261029040000','unused').active).toBe(false);
});

it('remembers cancellation before intervening weak INFO approach frames, but never before the latest delivery',()=>{
 const rows=['20261029035500','20261029035000','20261029034500','20261029034000'].map((t,i)=>({source_valid_at:t,event_type:i===0?'RAIN_APPROACHING':'RAIN_CLEAR',checked_at:`2026-10-29T03:${55-i*5}:00Z`}));
 const s=bootstrapForecastEpisode('old',{last_notified_at:'2026-10-29T03:00:00Z'},rows,'20261029040000');expect(s.approachNotified).toBe(false);expect(forecastEpisodeDecision(advanceForecastEpisode(s,'ACTIVE','20261029040000','new'),true,true,0,false).notify).toBe(true);
 expect(bootstrapForecastEpisode('old',{last_notified_at:'2026-10-29T03:54:00Z'},rows,'20261029040000').approachNotified).toBe(true);
});

